import { useEffect, useState } from "react";
import type { DateRange } from "react-day-picker";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { OdsButton } from "@/components/orderly/OdsButton";
import {
  OdsSegmentedControl,
  type OdsSegmentedControlItem,
} from "@/components/orderly/OdsSegmentedControl";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

export type DateRangePeriod = "7d" | "30d" | "90d" | "custom";
export type DateRangePresetPeriod = Exclude<DateRangePeriod, "custom">;

type CompleteDateRange = { from: Date; to: Date };

const DEFAULT_MAX_CUSTOM_RANGE_DAYS = 90;
const DAY_MS = 24 * 60 * 60 * 1000;
const START_CALENDAR_MONTH = new Date(2020, 0);
const MONTH_LABELS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

export const DATE_RANGE_PERIOD_ITEMS: ReadonlyArray<
  OdsSegmentedControlItem<DateRangePeriod>
> = [
  { value: "7d", label: "7D" },
  { value: "30d", label: "30D" },
  { value: "90d", label: "90D" },
];

function padDatePart(value: number) {
  return String(value).padStart(2, "0");
}

function formatDateUtc(date: Date) {
  return `${date.getUTCFullYear()}-${padDatePart(date.getUTCMonth() + 1)}-${padDatePart(date.getUTCDate())}`;
}

function parseDateString(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return undefined;
  return new Date(year, month - 1, day);
}

function formatCalendarDate(date: Date) {
  return `${date.getFullYear()}-${padDatePart(date.getMonth() + 1)}-${padDatePart(date.getDate())}`;
}

function calendarDayIndex(date: Date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_MS;
}

function getRangeDayCount(startDate: Date, endDate: Date) {
  return Math.abs(calendarDayIndex(endDate) - calendarDayIndex(startDate)) + 1;
}

function isRangeWithinMaxDays(startDate: Date, endDate: Date, maxDays: number) {
  return getRangeDayCount(startDate, endDate) <= maxDays;
}

function getUtcToday() {
  const now = new Date();
  return new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())
  );
}

function getTodayCalendarDate() {
  return parseDateString(formatDateUtc(getUtcToday())) || new Date();
}

function formatDateLabel(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return value || "-";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(Date.UTC(year, month - 1, day)));
}

function formatDateRangeLabel(startDate: string, endDate: string) {
  return `${formatDateLabel(startDate)} → ${formatDateLabel(endDate)}`;
}

export function getPresetDateRange(period: DateRangePresetPeriod) {
  const endDate = getUtcToday();
  const days = period === "7d" ? 7 : period === "30d" ? 30 : 90;
  const startDate = new Date(endDate.getTime() - (days - 1) * DAY_MS);
  return {
    startDate: formatDateUtc(startDate),
    endDate: formatDateUtc(endDate),
  };
}

export function validateDateRange(
  startDate: string,
  endDate: string,
  maxDays = DEFAULT_MAX_CUSTOM_RANGE_DAYS
) {
  if (!startDate || !endDate) return "Select both start and end dates.";
  const parsedStartDate = parseDateString(startDate);
  const parsedEndDate = parseDateString(endDate);
  if (!parsedStartDate || !parsedEndDate) {
    return "Select valid start and end dates.";
  }
  if (calendarDayIndex(parsedStartDate) > calendarDayIndex(parsedEndDate)) {
    return "Start date must be before end date.";
  }
  if (!isRangeWithinMaxDays(parsedStartDate, parsedEndDate, maxDays)) {
    return `Date range cannot exceed ${maxDays} days.`;
  }
  return "";
}

function createCalendarDateRange(
  startDate: string,
  endDate: string
): DateRange | undefined {
  const from = parseDateString(startDate);
  const to = parseDateString(endDate);
  if (!from || !to) return undefined;
  return { from, to };
}

function normalizeCalendarRange(from: Date, to: Date): CompleteDateRange {
  if (calendarDayIndex(from) <= calendarDayIndex(to)) return { from, to };
  return { from: to, to: from };
}

function isDateStrictlyInsideRange(date: Date, range: DateRange | undefined) {
  if (!range?.from || !range.to) return false;
  const day = calendarDayIndex(date);
  return day > calendarDayIndex(range.from) && day < calendarDayIndex(range.to);
}

function isDateDisabledForDraftRange(
  date: Date,
  openRangeAnchor: Date | undefined,
  maxDays: number
) {
  const today = getTodayCalendarDate();
  if (calendarDayIndex(date) > calendarDayIndex(today)) return true;
  if (!openRangeAnchor) return false;
  return !isRangeWithinMaxDays(openRangeAnchor, date, maxDays);
}

function monthIndex(date: Date) {
  return date.getFullYear() * 12 + date.getMonth();
}

function formatCalendarMonthLabel(date: Date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    year: "numeric",
  }).format(date);
}

export function DateRangeSelector({
  active,
  open,
  startDate,
  endDate,
  onOpenChange,
  onRangeChange,
  maxDays = DEFAULT_MAX_CUSTOM_RANGE_DAYS,
}: {
  active: boolean;
  open: boolean;
  startDate: string;
  endDate: string;
  onOpenChange: (open: boolean) => void;
  onRangeChange: (startDate: string, endDate: string) => void;
  maxDays?: number;
}) {
  const [draftRange, setDraftRange] = useState<DateRange | undefined>(() =>
    createCalendarDateRange(startDate, endDate)
  );
  const [openRangeAnchor, setOpenRangeAnchor] = useState<Date | undefined>();
  const [calendarMonth, setCalendarMonth] = useState(() => {
    const initialRange = createCalendarDateRange(startDate, endDate);
    return initialRange?.to || initialRange?.from || getTodayCalendarDate();
  });
  const [calendarView, setCalendarView] = useState<"days" | "months">("days");
  const today = getTodayCalendarDate();
  const calendarYear = calendarMonth.getFullYear();
  const minMonthIndex = monthIndex(START_CALENDAR_MONTH);
  const maxMonthIndex = monthIndex(today);
  const currentMonthIndex = monthIndex(calendarMonth);

  useEffect(() => {
    const nextRange = createCalendarDateRange(startDate, endDate);
    setDraftRange(nextRange);
    setOpenRangeAnchor(undefined);
    setCalendarMonth(nextRange?.to || nextRange?.from || today);
    setCalendarView("days");
  }, [endDate, startDate]);

  function changeCalendarMonth(monthOffset: number) {
    const nextMonth = new Date(
      calendarMonth.getFullYear(),
      calendarMonth.getMonth() + monthOffset,
      1
    );
    const nextMonthIndex = monthIndex(nextMonth);
    if (nextMonthIndex < minMonthIndex || nextMonthIndex > maxMonthIndex)
      return;
    setCalendarMonth(nextMonth);
  }

  function changeCalendarYear(yearOffset: number) {
    const nextYearMonth = new Date(calendarYear + yearOffset, 0, 1);
    const nextYearIndex = monthIndex(nextYearMonth);
    if (nextYearIndex > maxMonthIndex) return;
    if (nextYearIndex + 11 < minMonthIndex) return;
    setCalendarMonth(nextYearMonth);
  }

  function selectCalendarMonth(month: number) {
    const nextMonth = new Date(calendarYear, month, 1);
    const nextMonthIndex = monthIndex(nextMonth);
    if (nextMonthIndex < minMonthIndex || nextMonthIndex > maxMonthIndex)
      return;
    setCalendarMonth(nextMonth);
    setCalendarView("days");
  }

  function startNewDateRange(date: Date) {
    setOpenRangeAnchor(date);
    setDraftRange(undefined);
  }

  function handleDayClick(date: Date) {
    if (isDateDisabledForDraftRange(date, openRangeAnchor, maxDays)) return;
    if (!openRangeAnchor) {
      startNewDateRange(date);
      return;
    }

    const normalizedRange = normalizeCalendarRange(openRangeAnchor, date);
    if (
      !isRangeWithinMaxDays(normalizedRange.from, normalizedRange.to, maxDays)
    )
      return;
    setOpenRangeAnchor(undefined);
    setDraftRange(normalizedRange);
    onRangeChange(
      formatCalendarDate(normalizedRange.from),
      formatCalendarDate(normalizedRange.to)
    );
  }

  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <OdsButton
          type="button"
          aria-label={`Date range filter: ${formatDateRangeLabel(startDate, endDate)}`}
          size="small"
          variant={active ? "primary" : "secondary"}
          className="h-8 px-3 text-[12px]"
        >
          {formatDateRangeLabel(startDate, endDate)}
        </OdsButton>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        sideOffset={8}
        className="w-auto max-w-[480px] rounded-xl border border-(--line-subtle) bg-(--bg-popout) p-3 text-(--fg-primary) shadow-xl"
      >
        <div className="w-56">
          <div className="mb-3 grid grid-cols-[2rem_1fr_2rem] items-center gap-2">
            <button
              type="button"
              aria-label={
                calendarView === "months" ? "Previous year" : "Previous month"
              }
              disabled={
                calendarView === "months"
                  ? monthIndex(new Date(calendarYear - 1, 11, 1)) <
                    minMonthIndex
                  : currentMonthIndex <= minMonthIndex
              }
              onClick={() =>
                calendarView === "months"
                  ? changeCalendarYear(-1)
                  : changeCalendarMonth(-1)
              }
              className="flex size-8 items-center justify-center rounded-md text-[var(--fg-secondary)] transition-colors hover:bg-[var(--bg-secondary)] disabled:cursor-not-allowed disabled:opacity-35"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              type="button"
              onClick={() =>
                setCalendarView(view => (view === "months" ? "days" : "months"))
              }
              className="h-8 rounded-md px-2 text-center text-sm font-semibold text-[var(--fg-base)] transition-colors hover:bg-[var(--bg-secondary)]"
            >
              {calendarView === "months"
                ? calendarYear
                : formatCalendarMonthLabel(calendarMonth)}
            </button>
            <button
              type="button"
              aria-label={
                calendarView === "months" ? "Next year" : "Next month"
              }
              disabled={
                calendarView === "months"
                  ? monthIndex(new Date(calendarYear + 1, 0, 1)) > maxMonthIndex
                  : currentMonthIndex >= maxMonthIndex
              }
              onClick={() =>
                calendarView === "months"
                  ? changeCalendarYear(1)
                  : changeCalendarMonth(1)
              }
              className="flex size-8 items-center justify-center rounded-md text-[var(--fg-secondary)] transition-colors hover:bg-[var(--bg-secondary)] disabled:cursor-not-allowed disabled:opacity-35"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>

          {calendarView === "months" ? (
            <div className="grid grid-cols-3 gap-x-5 gap-y-4 py-1">
              {MONTH_LABELS.map((label, month) => {
                const optionMonthIndex = monthIndex(
                  new Date(calendarYear, month, 1)
                );
                const disabled =
                  optionMonthIndex < minMonthIndex ||
                  optionMonthIndex > maxMonthIndex;
                const selected =
                  calendarYear === calendarMonth.getFullYear() &&
                  month === calendarMonth.getMonth();
                return (
                  <button
                    key={label}
                    type="button"
                    disabled={disabled}
                    onClick={() => selectCalendarMonth(month)}
                    className={`rounded-md py-2 text-sm font-medium transition-colors disabled:cursor-not-allowed disabled:text-[var(--fg-placeholder)] disabled:opacity-35 ${selected ? "bg-[var(--bg-primary)] text-[var(--fg-base)]" : "text-[var(--fg-secondary)] hover:bg-[var(--bg-secondary)] hover:text-[var(--fg-base)]"}`}
                  >
                    {label}
                  </button>
                );
              })}
            </div>
          ) : (
            <Calendar
              month={calendarMonth}
              onMonthChange={setCalendarMonth}
              modifiers={{
                ...(draftRange?.from && draftRange.to
                  ? {
                      range_start: draftRange.from,
                      range_end: draftRange.to,
                      range_middle: (date: Date) =>
                        isDateStrictlyInsideRange(date, draftRange),
                    }
                  : {}),
                ...(openRangeAnchor ? { open_anchor: openRangeAnchor } : {}),
              }}
              modifiersClassNames={{
                open_anchor:
                  "[&_button]:border [&_button]:border-[var(--fg-brand)] [&_button]:bg-[var(--bg-primary)] [&_button]:text-[var(--fg-base)] [&_button]:ring-2 [&_button]:ring-[var(--fg-brand)] [&_button]:ring-offset-2 [&_button]:ring-offset-[var(--bg-popout)]",
              }}
              onDayClick={handleDayClick}
              startMonth={START_CALENDAR_MONTH}
              endMonth={today}
              disabled={date =>
                isDateDisabledForDraftRange(date, openRangeAnchor, maxDays)
              }
              weekStartsOn={1}
              className="p-0 text-[var(--fg-base)] [--cell-size:2rem]"
              classNames={{
                root: "w-fit",
                months: "flex",
                month: "flex w-full flex-col gap-2",
                nav: "hidden",
                month_caption: "hidden",
                caption_label: "hidden",
                weekdays: "flex",
                weekday:
                  "w-8 select-none text-center text-xs font-medium text-[var(--fg-secondary)]",
                week: "mt-1 flex w-full",
                day: "relative h-8 w-8 p-0 text-center",
                day_button:
                  "size-8 min-w-8 rounded-md text-sm font-normal text-[var(--fg-base)] hover:bg-[var(--bg-secondary)] disabled:cursor-not-allowed disabled:text-[var(--fg-placeholder)] disabled:opacity-35 data-[range-middle=true]:bg-[var(--bg-primary-subtle)] data-[range-middle=true]:text-[var(--fg-base)] data-[range-start=true]:bg-[var(--bg-primary)] data-[range-start=true]:text-[var(--fg-base)] data-[range-end=true]:bg-[var(--bg-primary)] data-[range-end=true]:text-[var(--fg-base)] data-[selected-single=true]:bg-[var(--bg-primary)] data-[selected-single=true]:text-[var(--fg-base)]",
                range_start: "rounded-l-md bg-[var(--bg-primary-subtle)]",
                range_middle: "rounded-none bg-[var(--bg-primary-subtle)]",
                range_end: "rounded-r-md bg-[var(--bg-primary-subtle)]",
                today:
                  "text-[var(--fg-brand)] [&_button]:border [&_button]:border-[var(--fg-brand)] [&_button]:text-[var(--fg-brand)]",
                outside: "text-[var(--fg-placeholder)] opacity-45",
                disabled: "text-[var(--fg-placeholder)] opacity-35",
              }}
            />
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

export function DateRangeSegmentedControl({
  value,
  onValueChange,
}: {
  value: DateRangePeriod;
  onValueChange: (value: DateRangePeriod) => void;
}) {
  return (
    <OdsSegmentedControl
      ariaLabel="Period presets"
      items={DATE_RANGE_PERIOD_ITEMS}
      onValueChange={onValueChange}
      value={value}
    />
  );
}
