function appendEndpointQuery(
  endpoint: string,
  params: Record<string, number | string | undefined>
) {
  const [path, queryString = ""] = endpoint.split("?");
  const searchParams = new URLSearchParams(queryString);
  Object.entries(params).forEach(([key, value]) => {
    if (value === undefined || value === "") return;
    searchParams.set(key, String(value));
  });
  const nextQueryString = searchParams.toString();
  return nextQueryString ? `${path}?${nextQueryString}` : path;
}

function appendUserQuery(endpoint: string, user: UserRow) {
  if (user.account_id)
    return appendEndpointQuery(endpoint, { user_account: user.account_id });
  if (user.address)
    return appendEndpointQuery(endpoint, { user_address: user.address });
  return endpoint;
}

function parseUtcDateStart(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return undefined;
  return Date.UTC(year, month - 1, day, 0, 0, 0, 0);
}

function parseUtcDateEnd(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return undefined;
  return Date.UTC(year, month - 1, day, 23, 59, 59, 999);
}

function getUserDetailDateRangeParams(
  item: UserDetailEndpoint,
  dateRange: UserDetailDateRangeState
) {
  if (USER_DETAIL_UNFILTERED_ENDPOINT_IDS.has(item.id)) return {};
  if (item.id === "volume") {
    return {
      start_date: dateRange.startDate,
      end_date: dateRange.endDate,
    };
  }

  const start = parseUtcDateStart(dateRange.startDate);
  const end = parseUtcDateEnd(dateRange.endDate);
  return {
    start_t: start,
    end_t: end,
  };
}

function cleanUserDetailFilter(value: string) {
  return value.trim() || undefined;
}

function getUserDetailFilterParams(
  item: UserDetailEndpoint,
  filters: UserDetailEndpointFilters
) {
  if (item.id === "orders") {
    const orderFilters = filters.orders;
    return {
      symbol: cleanUserDetailFilter(orderFilters.symbol),
      side: cleanUserDetailFilter(orderFilters.side),
      order_type: cleanUserDetailFilter(orderFilters.orderType),
      status: cleanUserDetailFilter(orderFilters.status),
      sort_by: cleanUserDetailFilter(orderFilters.sortBy),
    };
  }
  if (item.id === "algoOrders") {
    const algoOrderFilters = filters.algoOrders;
    return {
      symbol: cleanUserDetailFilter(algoOrderFilters.symbol),
      side: cleanUserDetailFilter(algoOrderFilters.side),
      order_type: cleanUserDetailFilter(algoOrderFilters.orderType),
      status: cleanUserDetailFilter(algoOrderFilters.status),
      algo_type: cleanUserDetailFilter(algoOrderFilters.algoType),
    };
  }
  if (item.id === "trades") {
    return {
      symbol: cleanUserDetailFilter(filters.trades.symbol),
    };
  }
  if (item.id === "funding") {
    return {
      symbol: cleanUserDetailFilter(filters.funding.symbol),
    };
  }
  return {};
}

function buildUserDetailEndpoint(
  item: (typeof USER_DETAIL_ENDPOINTS)[number],
  user: UserRow,
  page: number,
  dateRange: UserDetailDateRangeState,
  filters: UserDetailEndpointFilters
) {
  const endpointWithPage = item.paginated
    ? appendEndpointQuery(item.endpoint, {
        page,
        size: USER_DETAIL_PAGE_SIZE,
      })
    : item.endpoint;
  const endpointWithDateRange = appendEndpointQuery(
    endpointWithPage,
    getUserDetailDateRangeParams(item, dateRange)
  );
  const endpointWithFilters = appendEndpointQuery(
    endpointWithDateRange,
    getUserDetailFilterParams(item, filters)
  );
  return appendUserQuery(endpointWithFilters, user);
}

