function getUserDetailActiveFilterCount(
  endpointId: UserDetailFilterEndpointId,
  filters: UserDetailEndpointFilters
) {
  const defaults = getDefaultUserDetailEndpointFilters();
  if (endpointId === "orders") {
    return (["symbol", "side", "orderType", "status"] as const).filter(
      key => filters.orders[key].trim() !== defaults.orders[key]
    ).length;
  }
  if (endpointId === "algoOrders") {
    return (
      ["symbol", "side", "orderType", "status", "algoType"] as const
    ).filter(key => filters.algoOrders[key].trim() !== defaults.algoOrders[key])
      .length;
  }
  if (endpointId === "funding") {
    return (["symbol"] as const).filter(
      key => filters.funding[key].trim() !== defaults.funding[key]
    ).length;
  }
  return (["symbol"] as const).filter(
    key => filters.trades[key].trim() !== defaults.trades[key]
  ).length;
}

